import PasswordContext from "./password-context";
import React, { useState } from "react";

const PasswordProvider = (props) => {
    const[items,setItem]=useState([]);
     const totalQuantity = items.reduce((acc, item) => acc + item.amount, 0);
 
  const [showForm, setShowForm] = useState(false);
  const [openProduct, setOpenProduct] = useState(false);
  const handleForm = () => {
    setShowForm(true);
  };

  const closeForm = () => {
    setShowForm(false);
  };

  const handleProduct=()=>{
    setOpenProduct(true);
  }

   const itemHandler=()=>{
    setItem((prevItem)=> [...prevItem])
   }

  const passwordContext = {
    item:items,
    showForm,
     addItem: itemHandler,
    totalQuantity,
     openProduct,
    handleForm,
    closeForm,
    handleProduct,
  };

  return (
    <PasswordContext.Provider value={passwordContext}>
      {props.children}
    </PasswordContext.Provider>
  );
};
export default PasswordProvider;
